{"path": "/tmp/sv-6723ea59f77943cdad29467109deda09/Components/Pages/Catalog/CatalogPagination.razor", "file_text": "<nav class="catalog-pagination" aria-label="Product page navigation">
    <button class="page-btn"
            disabled="@(Page <= 1)"
            @onclick="@(() => GoToPage(Page - 1))">
        Previous
    </button>

    @for (int i = 1; i <= TotalPages; i++)
    {
        var pageNum = i;
        <button class="page-btn @(pageNum == Page ? "active" : "")"
                @onclick="@(() => GoToPage(pageNum))">
            @pageNum
        </button>
    }

    <button class="page-btn"
            disabled="@(Page >= TotalPages)"
            @onclick="@(() => GoToPage(Page + 1))">
        Next
    </button>
</nav>

@code {
    [Parameter]
    public int Page { get; set; }

    [Parameter]
    public int TotalPages { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }
}
"}

