    min-height: calc(100vh - 4rem);
}

.catalog-layout > :first-child {
    flex: 0 0 25%;
    max-width: 25%;
}

.catalog-main {
    flex: 1;
    padding: 1.5rem;
    min-width: 0;
}

.loading-state,
.error-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 4rem 1rem;
    text-align: center;
}

.error-state p {
    color: #dc3545;
    margin-bottom: 1rem;
}

.error-state button {
    padding: 0.5rem 1.5rem;
    border: none;
    border-radius: 4px;
    background: #0d6efd;
    color: #fff;
    font-weight: 600;
    cursor: pointer;
}

